/**
 * Orbits of a vertex under the group generated by the input matrices, by
 * reduced words up to a given length.
 *
 * A word s₁s₂…s_L acts as s₁·(s₂·(…(s_L·v))), so words are grown on the
 * LEFT: the vertex of s·w is s applied to the vertex of w. Every step is a
 * single generator acting on a canonical vertex, and the actions are memoized,
 * so the cost is governed by the size of the orbit rather than the number of
 * words. Inverses act through the adjugate (the same element of PGL₂).
 */

import { sub } from './localField.js';

const MAX_STORED_WORDS = 64;     // per vertex
const DEFAULT_WORD_BUDGET = 400000;

/** Letters g₁, g₁⁻¹, g₂, g₂⁻¹, …; letter 2i+1 is the inverse of letter 2i. */
export function makeLetters(place, matrices) {
    const letters = [];
    matrices.forEach((m, i) => {
        letters.push({ name: `g${sub(i + 1)}`, tex: `g_{${i + 1}}`, gen: i, inv: 2 * i + 1, g: place.prepare(m), mat: m });
        letters.push({ name: `g${sub(i + 1)}⁻¹`, tex: `g_{${i + 1}}^{-1}`, gen: i, inv: 2 * i, g: place.prepare(place.adjugate(m)), mat: place.adjugate(m) });
    });
    return letters;
}

export const wordString = (letters, w) => (w.length ? w.map((li) => letters[li].name).join('·') : 'e');
export const wordTex = (letters, w) => (w.length ? w.map((li) => letters[li].tex).join('') : 'e');

/** A memoized action of letters on vertices. */
export function makeActor(place, letters) {
    const memo = new Map();
    const act = (li, vt, vid = place.id(vt)) => {
        const key = `${li}|${vid}`;
        let r = memo.get(key);
        if (!r) {
            r = place.act(letters[li].g, vt);
            if (memo.size > 500000) memo.clear();
            memo.set(key, r);
        }
        return r;
    };
    /** w·v for a word (array of letter indices, leftmost acts last). */
    const actWord = (w, vt) => {
        for (let i = w.length - 1; i >= 0; i--) vt = act(w[i], vt);
        return vt;
    };
    return { act, actWord, memo };
}

/**
 * The orbit of `base` under reduced words of length ≤ maxLength.
 * Returns { orbitMap: Map(id → { vertex, words: [letter arrays], count, minLength }),
 *           wordCount, truncated, actor }.
 */
export function computeOrbit(place, base, letters, maxLength, { budget = DEFAULT_WORD_BUDGET } = {}) {
    const actor = makeActor(place, letters);
    const orbitMap = new Map();
    const record = (vt, vid, word) => {
        let e = orbitMap.get(vid);
        if (!e) { e = { vertex: vt, words: [], count: 0, minLength: word.length }; orbitMap.set(vid, e); }
        e.count++;
        if (e.words.length < MAX_STORED_WORDS) e.words.push(word);
        if (word.length < e.minLength) e.minLength = word.length;
    };
    const baseId = place.id(base);
    record(base, baseId, []);
    let level = [{ word: [], vt: base, vid: baseId }];
    let wordCount = 1, truncated = false;
    for (let len = 1; len <= maxLength && !truncated; len++) {
        const next = [];
        for (const w of level) {
            const first = w.word.length ? w.word[0] : -1;
            for (let li = 0; li < letters.length; li++) {
                if (first >= 0 && letters[first].inv === li) continue;     // keep words reduced
                const vt = actor.act(li, w.vt, w.vid);
                const vid = place.id(vt);
                const word = [li].concat(w.word);
                next.push({ word, vt, vid });
                record(vt, vid, word);
                if (++wordCount >= budget) { truncated = true; break; }
            }
            if (truncated) break;
        }
        level = next;
    }
    return { orbitMap, wordCount, truncated, actor };
}

/** Words (letter arrays) that fix the base vertex, shortest first, excluding the identity. */
export function stabilizerWords(orbitMap, baseId) {
    const e = orbitMap.get(baseId);
    if (!e) return [];
    return e.words.filter((w) => w.length).sort((a, b) => a.length - b.length);
}

/**
 * The permutation of the link P¹(F_q) of `vt` induced by a word fixing vt.
 * Returns an array perm with perm[i] = image of point i, where point 0 is ∞
 * (the parent) and point 1 + r is the child with digit r.
 */
export function linkPermutation(place, actor, word, vt) {
    const nbrs = place.neighbors(vt);
    const pointOf = (u) => {
        const lp = place.linkPoint(vt, u);
        return lp === Infinity ? 0 : 1 + lp;
    };
    return nbrs.map((u) => {
        const img = actor.actWord(word, u);
        if (place.dist(img, vt) !== 1) throw new Error('internal: word does not fix the vertex');
        return pointOf(img);
    });
}

/** Cycle decomposition, omitting fixed points: [[a, b, …], …]. */
export function cycles(perm) {
    const seen = new Array(perm.length).fill(false), out = [];
    for (let i = 0; i < perm.length; i++) {
        if (seen[i]) continue;
        const c = [];
        for (let j = i; !seen[j]; j = perm[j]) { seen[j] = true; c.push(j); }
        if (c.length > 1) out.push(c);
    }
    return out;
}

/** Translation length of g on the tree: max(0, v(det) − 2 v(tr)). */
export function translationLength(place, m) {
    const F = place.F;
    const tr = F.add(m.a, m.d);
    const det = F.sub(F.mul(m.a, m.d), F.mul(m.b, m.c));
    const vt = place.val(tr), vd = place.val(det);
    if (vt === Infinity) return 0;
    return Math.max(0, vd - 2 * vt);
}
